fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n == 0 {
        // Empty input: return two empty vectors
        (Vec::new(), Vec::new())
    } else if n == 1 {
        // Single element: first array contains the element, second is empty
        (a, Vec::new())
    } else {
        // Length > 1: split roughly in half, ensure both parts are shorter than original
        let mid = n / 2;
        let first = a[..mid].to_vec();
        let second = a[mid..].to_vec();
        (first, second)
    }
}